import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import 'package:go_router/go_router.dart'  import '../api/api_client.dart'  import '../providers/auth_provider.dart'    class LoginScreen extends ConsumerStatefulWidget {    const LoginScreen({super.key})      @override    ConsumerState<LoginScreen> createState() => _LoginScreenState()  }    class _LoginScreenState extends ConsumerState<LoginScreen> {    final _emailController = TextEditingController()    final _passwordController = TextEditingController()    final _formKey = GlobalKey<FormState>()    bool _isLoading = false    bool _obscurePassword = true      @override    void dispose() {      _emailController.dispose()      _passwordController.dispose()      super.dispose()    }      Future<void> _login() async {      if (!_formKey.currentState!.validate()) return        setState(() => _isLoading = true)      try {        await ApiClient().login(          _emailController.text.trim(),          _passwordController.text,        )        if (mounted) {          ref.read(authProvider.notifier).state = true          context.go('/')        }      } catch (e) {        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            SnackBar(              content: Text('Ошибка входа: $e'),              backgroundColor: Colors.red,            ),          )        }      } finally {        if (mounted) setState(() => _isLoading = false)      }    }      @override    Widget build(BuildContext context) {      return Scaffold(        body: SafeArea(          child: SingleChildScrollView(            padding: const EdgeInsets.all(24),            child: Form(              key: _formKey,              child: Column(                crossAxisAlignment: CrossAxisAlignment.stretch,                children: [                  const SizedBox(height: 40),                  // Logo                  Container(                    width: 80,                    height: 80,                    decoration: BoxDecoration(                      color: Theme.of(context).colorScheme.primary,                      borderRadius: BorderRadius.circular(20),                    ),                    child: const Icon(                      Icons.work_outline,                      size: 40,                      color: Colors.white,                    ),                  ),                  const SizedBox(height: 24),                  const Text(                    'Мир Самозанятых',                    style: TextStyle(                      fontSize: 28,                      fontWeight: FontWeight.bold,                    ),                    textAlign: TextAlign.center,                  ),                  const SizedBox(height: 8),                  Text(                    'Вход в личный кабинет',                    style: TextStyle(                      fontSize: 16,                      color: Colors.grey[600],                    ),                    textAlign: TextAlign.center,                  ),                  const SizedBox(height: 40),                    // Email                  TextFormField(                    controller: _emailController,                    keyboardType: TextInputType.emailAddress,                    decoration: InputDecoration(                      labelText: 'Email',                      prefixIcon: const Icon(Icons.email_outlined),                      border: OutlineInputBorder(                        borderRadius: BorderRadius.circular(12),                      ),                    ),                    validator: (value) {                      if (value == null || value.isEmpty) return 'Введите email'                      if (!value.contains('@')) return 'Неверный email'                      return null                    },                  ),                  const SizedBox(height: 16),                    // Password                  TextFormField(                    controller: _passwordController,                    obscureText: _obscurePassword,                    decoration: InputDecoration(                      labelText: 'Пароль',                      prefixIcon: const Icon(Icons.lock_outline),                      suffixIcon: IconButton(                        icon: Icon(                          _obscurePassword ? Icons.visibility_off : Icons.visibility,                        ),                        onPressed: () => setState(() => _obscurePassword = !_obscurePassword),                      ),                      border: OutlineInputBorder(                        borderRadius: BorderRadius.circular(12),                      ),                    ),                    validator: (value) {                      if (value == null || value.isEmpty) return 'Введите пароль'                      if (value.length < 6) return 'Минимум 6 символов'                      return null                    },                  ),                  const SizedBox(height: 8),                  Align(                    alignment: Alignment.centerRight,                    child: TextButton(                      onPressed: () {},                      child: const Text('Забыли пароль?'),                    ),                  ),                  const SizedBox(height: 16),                    // Login button                  ElevatedButton(                    onPressed: _isLoading ? null : _login,                    style: ElevatedButton.styleFrom(                      padding: const EdgeInsets.symmetric(vertical: 16),                      shape: RoundedRectangleBorder(                        borderRadius: BorderRadius.circular(12),                      ),                    ),                    child: _isLoading                      ? const SizedBox(                          height: 20,                          width: 20,                          child: CircularProgressIndicator(strokeWidth: 2),                        )                      : const Text(                          'Войти',                          style: TextStyle(fontSize: 16),                        ),                  ),                  const SizedBox(height: 16),                    // Register link                  Row(                    mainAxisAlignment: MainAxisAlignment.center,                    children: [                      Text(                        'Нет аккаунта? ',                        style: TextStyle(color: Colors.grey[600]),                      ),                      TextButton(                        onPressed: () => context.push('/register'),                        child: const Text('Зарегистрироваться'),                      ),                    ],                  ),                ],              ),            ),          ),        ),      )    }  }